mapper.select:
SELECT COUNT(*)
FROM TB_CHAT_MESSAGE_READ
WHERE MESSAGE_KEY = #{messageKey}
AND USER_KEY = #{userKey}

mapper.insert:
INSERT INTO TB_CHAT_MESSAGE_READ (
MESSAGE_READ_KEY,
MESSAGE_KEY,
USER_KEY
)
VALUES (
#{messageReadKey},
#{messageKey},
#{userKey}
)

mapper.update:
UPDATE TB_CHAT_ROOM_USER
SET
    LAST_READ_AT = NOW(),
    UPDATED_AT = NOW()

WHERE ROOM_KEY = #{roomKey}
    AND USER_KEY = #{userKey}

mapper.select:
SELECT M.MESSAGE_KEY
FROM TB_CHAT_MESSAGE M
WHERE M.ROOM_KEY = #{roomKey}
    AND M.SENDER_USER_KEY != #{userKey}
    AND M.DELETED_YN = 'N'
    AND M.CREATED_AT >
COALESCE(
(
    SELECT LAST_READ_AT
    FROM TB_CHAT_ROOM_USER
    WHERE ROOM_KEY = #{roomKey}
        AND USER_KEY = #{userKey}
),
'1970-01-01'
)
